"""Task that runs a document retriever on a single dataset item.

Builds the local retriever once from ``config.retrieval`` and reuses it across
all items.
"""

import time
from typing import Any, Optional

import structlog
import tiktoken

from rasa.builder import config as builder_config
from rasa.builder.document_retrieval.base import BaseRetriever, RetrievalStatus
from rasa.builder.evaluator.configs.models import (
    ExperimentConfig,
    RetrievalTaskConfig,
)
from rasa.builder.evaluator.dataset.retrieval_models import RetrievalDatasetEntry
from rasa.builder.evaluator.tasks.base import BaseTask, RetrievalTaskResult

structlogger = structlog.get_logger()

# Fallback encoding for GPT-4.1/4o-class models when the exact (dated) model
# name is not in tiktoken's registry.
_FALLBACK_ENCODING = "o200k_base"


def _encoding_for_model(model_name: str) -> tiktoken.Encoding:
    """Resolve the tiktoken encoding for the downstream consumer model."""
    try:
        return tiktoken.encoding_for_model(model_name)
    except KeyError:
        return tiktoken.get_encoding(_FALLBACK_ENCODING)


class RetrievalTask(BaseTask):
    """Callable task that runs a document retriever on a single dataset item."""

    def __init__(self, config: ExperimentConfig) -> None:
        super().__init__(config)
        if config.retrieval is None:
            raise ValueError("task='retrieval' requires a 'retrieval' config block.")
        self._retriever = self._build_retriever(config.retrieval)
        # Tokenize with the model that consumes retrieved docs downstream, so
        # token counts reflect real LLM context cost.
        self._encoding = _encoding_for_model(builder_config.OPENAI_MODEL)

    @staticmethod
    def _build_retriever(config: RetrievalTaskConfig) -> BaseRetriever:
        """Build the local retriever over the configured docs checkout."""
        from rasa.builder.document_retrieval.corpus import MintlifyCheckoutSource
        from rasa.builder.document_retrieval.local.retrieval import (
            LocalDocumentRetrieval,
        )
        from rasa.builder.document_retrieval.mintlify import RASA_DOCS_SITE

        # Pull the corpus through the CorpusSource seam, so the task does not
        # depend on the docs parser directly.
        site = RASA_DOCS_SITE
        documents, corpus_version = MintlifyCheckoutSource(
            config.docs_repo_path, site
        ).load()
        return LocalDocumentRetrieval.from_documents(
            config.local, documents, corpus_version, corpus=site.source
        )

    async def run_task(
        self,
        *,
        item: Any,
        **_: Any,
    ) -> Optional[RetrievalTaskResult]:
        """Run the retriever on a single dataset item.

        Args:
            item: Langfuse ExperimentItem.

        Returns:
            RetrievalTaskResult. On retrieval failure, the result contains
            ``error`` set and empty ``retrieved_urls``. Returns None only if
            the item itself cannot be parsed.
        """
        try:
            dataset_entry = RetrievalDatasetEntry.from_raw_data(
                id=item.id,
                input_data=item.input,
                expected_output_data=item.expected_output,
                metadata_data=item.metadata,
            )
        except Exception as e:
            structlogger.error(
                "tasks.retrieval_task.item_parse_failed",
                item_id=getattr(item, "id", None),
                error=str(e),
            )
            return None

        query = dataset_entry.input.query

        try:
            start = time.monotonic()
            response = await self._retriever.retrieve(query)
            latency_ms = (time.monotonic() - start) * 1000

            if response.status is RetrievalStatus.ERROR:
                return RetrievalTaskResult(
                    query=query,
                    retrieved_urls=[],
                    retrieved_titles=[],
                    latency_ms=0.0,
                    error=response.error,
                )

            results = response.results
            retrieved_urls = [r.url for r in results if r.url]
            retrieved_titles = [r.title or "" for r in results if r.url]
            # Count tokens over ALL returned results (true downstream context
            # cost), independent of whether a result carries a URL.
            retrieved_tokens = sum(
                len(self._encoding.encode(r.content)) for r in results if r.content
            )

            return RetrievalTaskResult(
                query=query,
                retrieved_urls=retrieved_urls,
                retrieved_titles=retrieved_titles,
                latency_ms=latency_ms,
                retrieved_tokens=retrieved_tokens,
            )
        except Exception as e:
            structlogger.error(
                "tasks.retrieval_task.retrieval_failed",
                item_id=item.id,
                query=query,
                error=str(e),
            )
            return RetrievalTaskResult(
                query=query,
                retrieved_urls=[],
                retrieved_titles=[],
                latency_ms=0.0,
                error=str(e),
            )
